const fs=require("node:fs"),cp=require("node:child_process"),crypto=require("node:crypto");
const d="docs/coordinator/worktree-completion/evidence/",sha=b=>crypto.createHash("sha256").update(b).digest("hex"),commands=[],failures=[];
const cmd=(exe,args)=>{const r=cp.spawnSync(exe,args,{encoding:"utf8",maxBuffer:32*1024*1024});commands.push({executable:exe,args,cwd:process.cwd(),exit:r.status,signal:r.signal,stdout:r.stdout,stderr:r.stderr});if(r.status!==0)failures.push(exe+" "+args.join(" ")+" exit "+r.status);return r.stdout};
const git=(...a)=>cmd("git",a),check=(ok,name)=>{if(!ok)failures.push(name)};
const read=p=>JSON.parse(fs.readFileSync(d+p));
const final=read("dcc1-parity-observer-proof-final-inventory.json"),old=read("dcc1-ae007-postflight.json"),proof=read("dcc1-parity-observer-proof-preflight.json"),patch=read("dcc1-parity-observer-patch.json");
const info=path=>{const s=fs.lstatSync(path);check(s.isFile()&&!s.isSymbolicLink(),"regular file "+path);const b=fs.readFileSync(path);return{path,bytes:b.length,sha256:sha(b),mode:s.mode&4095}};
const head=git("rev-parse","HEAD").trim(),merge=git("rev-parse","MERGE_HEAD").trim(),index=git("write-tree").trim();
check(head===final.head&&merge===final.merge&&index===final.index,"parents/index");
const stream=git("ls-tree","-r","--full-tree",index).split("\n").filter(l=>l&&!/\tdocs\/coordinator\/worktree-completion\/(reports|evidence|handoffs)\//.test(l)).join("\n")+"\n";
check(sha(stream)==="d681c0c5a4d7e2764d40f231e1f5f3650a838b044264a5a37077235de1f18051","closure");
const lines=git("ls-files","-s").trimEnd().split("\n").filter(l=>!l.includes("\tdocs/coordinator/worktree-completion/"));let tracked=0;
for(const l of lines){const[m,p]=l.split("\t"),[mode,expected,stage]=m.split(" "),b=mode==="120000"?Buffer.from(fs.readlinkSync(p)):fs.readFileSync(p);const actual=crypto.createHash("sha1").update(Buffer.concat([Buffer.from("blob "+b.length+"\0"),b])).digest("hex");check(actual===expected&&stage==="0","tracked "+p);tracked++}
const untracked=git("ls-files","--others","--exclude-standard","-z").split("\0").filter(Boolean).map(info);
const ledgerPath=d+"dcc1-parity-observer-preflight-correction-final-inventory.json",ledgerBytes=fs.readFileSync(ledgerPath);
check(ledgerBytes.length===119777&&sha(ledgerBytes)==="39a8dedf4b15a764dd512903342d0e72b40fbc810d1263d692c9b7acc44906ff","approved ledger bytes");
const approved=JSON.parse(ledgerBytes).record.untracked;
check(approved.length===277,"approved 277 records");
const expected=[...approved,{path:ledgerPath,bytes:119777,sha256:"39a8dedf4b15a764dd512903342d0e72b40fbc810d1263d692c9b7acc44906ff",mode:420}];
check(untracked.length===278,"278 untracked");
const by=new Map(untracked.map(x=>[x.path,x]));for(const x of expected){const now=by.get(x.path);check(now&&now.bytes===x.bytes&&now.sha256===x.sha256&&now.mode===x.mode,"prior untracked "+x.path)}check(untracked.every(x=>expected.some(y=>y.path===x.path)),"untracked exact membership");
const retained=[...old.bundle.inputs,...old.bundle.outputs,old.bundle.stampFile,...old.parityArtifacts,...old.coverageArtifacts,...old.evidence,...old.archives.flatMap(x=>[{path:x.path,bytes:x.originalBytes,sha256:x.originalSha256},{path:x.archivePath,bytes:x.archiveBytes,sha256:x.archiveSha256}]),...proof.untrackedPins,proof.parent];
for(const x of retained){const n=info(x.path);check(n.bytes===x.bytes&&n.sha256===x.sha256,"retained "+x.path)}
const absent=[...proof.proposed.map(x=>x.path),d+"dcc1-parity-observer-diagnostic.raw.log",d+"dcc1-parity-observer-diagnostic.meta.jsonl",d+"dcc1-parity-observer-diagnostic-preserved"];
for(const p of absent)check(!fs.existsSync(p),"must be absent "+p);
check(sha(patch.patch)==="bb49d8eaee199691cc432f295625d2fcd631a50fa63a53d6419a5bbcc1eef781","patch bytes");
const deps=old.checks.filter(x=>x.name.startsWith("dependency ")).map(x=>{const p=x.name.slice(11),n=info(p);check(n.sha256===x.expected,"dependency "+p);return n});
const graph=cmd("npm",["ls","--all","--json"]);check(sha(graph)===old.checks.find(x=>x.name==="npm graph").expected,"npm graph");
const legacy="/Users/julianhein/Projects/hr-automation";
check(git("-C",legacy,"rev-parse","HEAD").trim()===old.checks.find(x=>x.name==="legacy HEAD").expected,"legacy HEAD");
check(git("-C",legacy,"status","--porcelain","--untracked-files=no").trim()===old.checks.find(x=>x.name==="legacy dirty").expected,"legacy dirty");
for(const x of old.checks.filter(x=>x.name.startsWith("legacy guard "))){check(info(legacy+"/"+x.name.slice(13)).sha256===x.expected,x.name)}
check(git("diff","--name-only").trim()==="docs/coordinator/worktree-completion/reports/dcc1.md","only known parent unstaged");check(git("ls-files","-u")==="","unmerged empty");git("diff","--check");git("diff","--cached","--check");
const preserve=[...old.bundle.outputs,old.bundle.stampFile,...old.parityArtifacts,...old.evidence].map(x=>info(x.path));
const out={classification:"Read-only preflight, structured command/output metadata (not raw child output)",at:new Date().toISOString(),cwd:process.cwd(),head,merge,index,executionClosure:sha(stream),trackedCount:tracked,untracked,retainedCount:retained.length,absent,dependencies:deps,npmGraphSha256:sha(graph),preserve,oldStamp:old.bundle.stamp,commands,failures,pass:failures.length===0};
console.log(JSON.stringify(out));process.exitCode=failures.length?1:0;

